function renderServicesPage({MODEL,$,fmt,esc,core,factBtn,sheetBtn,heading,servicePlacement,serviceDetailButtons,showServiceInModel}){
 const sites=MODEL.services.map(s=>servicePlacement(s,true));
 const X=MODEL.axis_view_variant.x,Y=MODEL.axis_view_variant.y;
 const svg=`<svg class="plan-svg" viewBox="-1900 -18500 20500 20500" role="img" aria-label="Координаты закладных по осям в плане. Сетка X условна: сумма частей 13870, общий размер 13865."><g transform="scale(1,-1)">${Object.entries(X).map(([a,x])=>`<path d="M${x},-1000V17000" stroke="#b9c7b0" stroke-width="15" stroke-dasharray="160 130"/>`).join('')}${Object.entries(Y).map(([a,y])=>`<path d="M-1100,${y}H18000" stroke="#c5cfba" stroke-width="15" stroke-dasharray="160 130"/>`).join('')}<polygon points="${core.map(p=>p.join(',')).join(' ')}" fill="#dfe8d4" stroke="#738e6a" stroke-width="40"/>${sites.map(s=>`<g tabindex="0" role="button" aria-label="${s.label}" data-service="${s.id}" style="cursor:pointer"><circle cx="${s.x_mm}" cy="${s.y_mm}" r="210" fill="${s.id==='electric'?'#d3ac50':s.id==='В1-1'?'#659bba':'#ba774b'}" stroke="white" stroke-width="45"/><circle cx="${s.x_mm}" cy="${s.y_mm}" r="390" fill="transparent"/></g>`).join('')}</g>${Object.entries(X).map(([a,x])=>`<text x="${x}" y="900" font-size="250" text-anchor="middle" fill="#657e5c">${a}</text>`).join('')}${Object.entries(Y).map(([a,y])=>`<text x="-1250" y="${-y+80}" font-size="240" fill="#657e5c">${a}</text>`).join('')}${sites.map((s,i)=>`<text x="${+s.x_mm+330}" y="${-s.y_mm+(i===2?-200:160)}" font-size="230" fill="#435d3a">${s.id==='electric'?'Эл.':s.label}</text>`).join('')}<text x="7000" y="-17400" font-size="225" fill="#9a6e34">XY по сумме частей X · контур на проверке</text></svg>`;
 $('page-services').innerHTML=heading('03 / ВОДА · КАНАЛИЗАЦИЯ · ЭЛЕКТРИЧЕСТВО','Закладные до бетонирования','Редакция ВК-1 от 18.11.2026. Ввод воды В1-1 перенесён к оси Е. Привязки остальных гильз взяты из исходного ВК-1 от 06.26. Абсолютные высоты труб, длины гильз и полный монтажный маршрут не назначены.')+`<div class="callout"><b>I005 / I008 · требуется согласование редакций</b>На КЖ-2 выноска воды Ø63, размер над трубой 65; на ВК-1 — Ø32. Отметку −0.500 в рамке нельзя считать осью каждой трубы. Лист ВК-1 пользователь назвал примерным.</div><div class="service-layout" style="margin-top:25px"><div>${svg}<div class="legend"><span><i style="--c:#ba774b"></i>Канализация Ø110</span><span><i style="--c:#659bba"></i>Вода Ø32</span><span><i style="--c:#d3ac50"></i>Предполагаемый эл. ввод</span></div><div class="card"><h3>Что означают координаты</h3><p>Начало для просмотра — пересечение осей 1 и А. X вправо, Y к И. X рассчитан суммой подписанных частей 1065 + 5470 + 2595 + 3140 + 1600 = 13870 мм; общий размер 13865 сохранён отдельно.</p><p>Показанный вариант не разрешает расхождение 5 мм. Прямоугольный маркер в 3D — обозначение точки, не фактическая длина прохода.</p>${sheetBtn('embeds',1,'ВК-1 · принятая редакция','revision')}${sheetBtn('embeds',1,'ВК-1 · исходный лист')}${sheetBtn('house_2',7,'КЖ-2 · детали вводов и выпуска')}</div></div><div>${sites.map(s=>`<div class="service-card"><h3>${s.label}<span class="status amber">Z не задан</span></h3><p>${s.diameter?'Труба Ø'+s.diameter+' мм · ':''}стальная гильза Ø${s.sleeve} мм${s.id==='electric'?' · место предполагаемого ввода кабеля':''}</p><p>Ось ${s.anchor_x}: ${fmt(Math.abs(+s.offset_x_mm))} мм ${+s.offset_x_mm>=0?'вправо':'влево'} · ось ${s.anchor_y}: ${fmt(Math.abs(+s.offset_y_mm))} мм ${+s.offset_y_mm>=0?'к И':'к А'}</p><div class="coords">derived: X=${s.x_mm}; Y=${s.y_mm} мм</div><div class="buttons-row"><button data-service-open="${s.id}">Показать в 3D</button>${factBtn('service.'+s.id+'.steel_sleeve_diameter','Источник')}</div></div>`).join('')}</div></div><div class="card"><h3>Выпуск под фундаментом</h3><p>На КЖ-2 показаны труба ПП Ø110, гильза Ø200×4, колено 45° и уклон i=0,02. Это детали проекта 04.23. Они не задают полную высотную трассу примерной схемы 06.26. Длину канализационных труб и уклон каждого участка по этой 3D-схеме не считаем.</p>${factBtn('service.legacy_outlet.slope','Уклон в детали КЖ-2')}</div>`;
 $('page-services').querySelector('.service-layout').insertAdjacentHTML('beforebegin','<div class="buttons-row"><button data-anchor-plan="К1-1">Измерить между гильзами на плане ↗</button><button data-sleeve-review>Гильзы и арматура</button><button data-service-takeoff>Обмер труб и проходок</button></div>');
 $('page-services').insertAdjacentHTML('beforeend',serviceDetailButtons());
 $('page-services').addEventListener('click',e=>{const t=e.target.closest('[data-service-open],[data-service]');if(t){const id=t.dataset.serviceOpen||t.dataset.service;showServiceInModel(id);}});$('page-services').addEventListener('keydown',e=>{const t=e.target.closest('[data-service]');if(t&&(e.key==='Enter'||e.key===' ')){e.preventDefault();t.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
}

export { renderServicesPage };
